import functools
from typing import ForwardRef
from fastapi.dependencies.utils import get_typed_signature

# Simulate Module A
def module_a():
    class MyModel:
        pass

    def original_func(x: "MyModel"):
        return x

    return original_func, MyModel

# Simulate Module B
def module_b(original_func):
    @functools.wraps(original_func)
    def wrapper(x): # annotations are copied from original_func
        return original_func(x)
    return wrapper

original_func, MyModel = module_a()
wrapper = module_b(original_func)

# Now wrapper.__annotations__ contains {'x': 'MyModel'}
# But wrapper.__globals__ is the globals of module_b, which doesn't have MyModel.
# original_func.__globals__ has MyModel.

try:
    sig = get_typed_signature(wrapper)
    print("Success!")
except NameError as e:
    print(f"Caught NameError: {e}")
except Exception as e:
    import traceback
    traceback.print_exc()

